SELECT      c.id AS "Id do curso",     c.fullname AS "Curso",     COUNT(DISTINCT ue.id) AS "Total de usuários inscritos",     COUNT(DISTINCT CASE          WHEN cc.timecompleted IS NOT NULL          THEN cc.userid      END) AS "Total de usuários concluídos",     ROUND(         (COUNT(DISTINCT CASE              WHEN cc.timecompleted IS NOT NULL              THEN cc.userid          END) / NULLIF(COUNT(DISTINCT ue.id), 0)) * 100,         2     ) AS "% Índice de conclusão" FROM      mdl_course c LEFT JOIN      mdl_enrol e ON c.id = e.courseid LEFT JOIN      mdl_user_enrolments ue ON e.id = ue.enrolid LEFT JOIN      mdl_user u ON ue.userid = u.id      AND u.deleted = 0      AND u.suspended = 0 LEFT JOIN      mdl_course_completions cc ON cc.course = c.id      AND cc.userid = ue.userid LEFT JOIN      mdl_customfield_field cff ON cff.shortname = 'obs' LEFT JOIN      mdl_customfield_data cfd ON cfd.fieldid = cff.id      AND cfd.instanceid = c.id WHERE      c.visible = 1     AND c.fullname NOT LIKE '%senac%'     AND (cfd.value IS NULL OR cfd.value != '1') GROUP BY      c.id,      c.fullname ORDER BY      "% Índice de conclusão" DESC LIMIT 5;
